mapper.select:
select 
from practice_generated_content
where owner_scope = #{ownerScope}
  and owner_key = #{ownerKey}
  and owner_key_version = #{ownerKeyVersion}
  and client_request_id = #{clientRequestId}
limit 1

select 
from practice_generated_content
where owner_key = #{ownerKey}
  and owner_key_version = #{ownerKeyVersion}
  and surface = #{surface}
  and mode = #{mode}
  and request_fingerprint = #{requestFingerprint}
  and generation_profile_version = #{generationProfileVersion}
  and content_refresh_epoch = #{contentRefreshEpoch}
  and status in ('draft', 'generating', 'active')
order by case status when 'active' then 0 when 'generating' then 1 else 2 end,
         updated_at desc, generated_content_id asc
limit 1

select 
from practice_generated_content
where owner_key = #{ownerKey}
  and owner_key_version = #{ownerKeyVersion}
  and surface = #{surface}
  and mode = #{mode}
  and request_fingerprint = #{requestFingerprint}
  and generation_profile_version = #{generationProfileVersion}
  and content_refresh_epoch = #{contentRefreshEpoch}
  and status = 'active'
  and (owner_scope <> 'installation'
       or retention_expires_at > #{reusableAt,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler})
order by updated_at desc, generated_content_id asc
limit 1

select count(*)
from practice_generated_content
where owner_key = #{ownerKey}
  and owner_key_version = #{ownerKeyVersion}
  and surface = #{surface}
  and mode = #{mode}
  and created_at >= #{createdAtFrom,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}

select 
from practice_generated_content
where owner_scope = 'installation'
  and owner_key_version = #{ownerKeyVersion}
  and installation_ref_hash = #{installationRefHash}
  and status in ('active', 'expired', 'rejected')
  and retention_expires_at <= #{retentionExpiresAtOrBefore,typeHandler=org.apache.ibatis.type.OffsetDateTimeTypeHandler}
order by retention_expires_at asc, generated_content_id asc
limit #{limit}
